import {test,expect} from '@playwright/test';
import {initialREA,analyticsREA} from '../../supabase/functions/bitbot-v10/rea-core.mjs';
import {REVIEW_ROLES} from '../../supabase/functions/bitbot-v10/rea-review-team.mjs';
import {EXPERIMENT_PROFILES,experimentReview} from '../../supabase/functions/bitbot-v10/rea-experiments.mjs';
async function setup(page,{signed=true,stale=false,live=null,codex=null,codexConfigFailure=null,path='/rea.html#paper'}={}){
 const now=Date.now(),s=initialREA(now),data={mode:'PAPER_ONLY',enabled:true,state:s,latest:{at:stale?now-300000:now,health:'OK',universe:347,summary:analyticsREA(s),decisions:[{symbol:'BTC_THB',score:66,reference:3000000,priceAt:now,strategy:null,reason:'NO_COMPLETE_STRATEGY'}],agents:[{role:'Risk Manager',at:now,status:'COMPLETED',reason:'PAPER_ONLY'}]},curve:[{at_ms:now-60000,equity:10000},{at_ms:now,equity:10000}],daily:[],audit:[]},calls=[],errors=[];
 page.on('pageerror',e=>errors.push(e.message));await page.route('https://fonts.googleapis.com/**',r=>r.abort());
 await page.route('https://cdn.jsdelivr.net/**',r=>r.fulfill({contentType:'text/javascript',body:`globalThis.__testAuthSession=${signed?JSON.stringify({access_token:'QA_ONLY',user:{id:'test-owner'}}):'null'};export const createClient=()=>({auth:{onAuthStateChange(fn){globalThis.__testAuthChange=fn;},getSession:async()=>({data:{session:globalThis.__testAuthSession}})}});`}));
 await page.route('**/functions/v1/bitbot-v10?**',async r=>{const a=new URL(r.request().url()).searchParams.get('action'),body=r.request().postData()?JSON.parse(r.request().postData()):{};calls.push({a,body});if(a==='rea-codex-config'&&codexConfigFailure?.message){await r.fulfill({status:503,json:{ok:false,error:codexConfigFailure.message}});return;}if(a==='rea-codex-config'){codex={...codex,configured:!!body.apiKey||codex?.configured===true,enabled:body.enabled,consent:body.consent,dailyCalls:codex?.dailyCalls||0,jobs:codex?.jobs||[],canTrade:false};}if(a==='rea-control'){if(body.action==='pause')s.buyPaused=true;if(body.action==='resume')s.buyPaused=false;if(body.action==='emergency')s.kill='ALL';}await r.fulfill({json:a==='rea-codex-state'?{ok:true,codex:codex||{configured:false,enabled:false,consent:false,dailyCalls:0,jobs:[],canTrade:false}}:a==='rea-codex-config'?{ok:true,codex}:a==='rea-codex-request'?{ok:true,queued:true}:a==='rea-live-state'?{ok:true,live}:a==='keys'?{ok:true,verified:true,wallet:{at:Date.now(),THB:{available:99.97,reserved:0}}}:{ok:true,rea:data,saved:true}});});
 await page.goto('http://127.0.0.1:4173'+path);return{data,calls,errors};
}
test('REA renders only backend paper data and does not start or submit on load',async({page})=>{const {calls,errors}=await setup(page);await expect(page.locator('#reaEquity')).toHaveText('฿10,000.00');await expect(page.locator('#reaMode')).toHaveText('PAPER_ONLY');await expect(page.locator('#reaSlots')).toHaveText('0 / 2');expect(calls.every(c=>['rea-state','rea-live-state','rea-codex-state'].includes(c.a))).toBeTruthy();expect(errors).toEqual([]);});
test('pause, resume and emergency issue authenticated controls without an order endpoint',async({page})=>{const {calls,data}=await setup(page);await expect(page.locator('#reaEquity')).toContainText('10,000');await page.locator('[data-rea-page=safety]').click();await page.locator('[data-rea-control=pause]').click();await expect(page.locator('#reaControlState')).toContainText('Pause: true');await page.locator('[data-rea-control=resume]').click();await page.locator('[data-rea-control=emergency]').click();await expect(page.locator('#reaMode')).toHaveText('EMERGENCY_STOP');expect(data.state.kill).toBe('ALL');expect(calls.filter(c=>c.a==='rea-control').map(c=>c.body.action)).toEqual(['pause','resume','emergency']);expect(calls.some(c=>/start|submit|tick|wallet/.test(c.a))).toBeFalsy();});
test('all six pages fit mobile in light mode and scanner explains waiting',async({page})=>{await page.setViewportSize({width:390,height:844});const {errors}=await setup(page);await expect(page.locator('#reaEquity')).toContainText('10,000');await page.locator('#reaTheme').click();await expect(page.locator('html')).toHaveAttribute('data-theme','light');for(const name of ['overview','scanner','orders','profit','agents','safety']){await page.locator('[data-rea-page='+name+']').click();expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),"Mobile page: "+name).toBeTruthy();}await page.locator('[data-rea-page=scanner]').click();await expect(page.locator('#reaScanner')).toContainText('รอชุดสัญญาณซื้อที่สมบูรณ์');expect(errors).toEqual([]);});
